<?php
require __DIR__.'/includes/bootstrap.php';require_auth();require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';
if($_SERVER['REQUEST_METHOD']==='POST')enforce_branch_scope((int)($_POST['from_branch_id']??0));
if($_SERVER['REQUEST_METHOD']==='POST'){require_permission('transfers.create');verify_csrf();$from=(int)$_POST['from_branch_id'];$to=(int)$_POST['to_branch_id'];$brand=(int)$_POST['brand_id'];$product=(int)$_POST['product_id'];$qty=(float)$_POST['quantity'];if($from===$to||$qty<=0){flash('error','Choose different branches and a valid quantity.');redirect('transfers.php?action=create');}try{$pdo->beginTransaction();$ref=next_reference($pdo,'TRF','stock_transfers');$s=$pdo->prepare('INSERT INTO stock_transfers(reference_no,transfer_date,from_branch_id,to_branch_id,brand_id,status,notes,requested_by,approved_by,received_by) VALUES(?,?,?,?,?,"received",?,?,?,?)');$s->execute([$ref,$_POST['date'],$from,$to,$brand,$_POST['notes']??'',user()['id'],user()['id'],user()['id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO stock_transfer_items(transfer_id,product_id,quantity) VALUES(?,?,?)')->execute([$id,$product,$qty]);ledger($pdo,['product_id'=>$product,'branch_id'=>$from,'brand_id'=>$brand,'transaction_type'=>'transfer_out','reference_type'=>'transfer','reference_id'=>$id,'reference_no'=>$ref,'quantity_in'=>0,'quantity_out'=>$qty]);ledger($pdo,['product_id'=>$product,'branch_id'=>$to,'brand_id'=>$brand,'transaction_type'=>'transfer_in','reference_type'=>'transfer','reference_id'=>$id,'reference_no'=>$ref,'quantity_in'=>$qty,'quantity_out'=>0]);audit($pdo,'create','transfers',$id,null,['reference'=>$ref]);$pdo->commit();flash('success','Transfer '.$ref.' completed and both branch ledgers updated.');redirect('transfers.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());redirect('transfers.php?action=create');}}
$create=($_GET['action']??'')==='create';$branches=options($pdo,'branches');$brands=options($pdo,'brands');$products=options($pdo,'products');render_header('Transfers','transfers');page_title('Stock Transfers','INTER-BRANCH MOVEMENT','Move inventory between branches with paired ledger entries.',$create?'':'New Transfer',app_url('transfers.php?action=create'));
if($create):?><article class="card form-card"><div class="card-head"><div><h2>New stock transfer</h2><small>Available stock is validated before transfer.</small></div><span class="status">AUDITED</span></div><form method="post"><?=csrf_field()?><div class="form-grid"><label>Date<input type="date" name="date" value="<?=date('Y-m-d')?>" required></label><label>Brand<select name="brand_id" required><option value="">Select brand</option><?php foreach($brands as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>From branch<select name="from_branch_id" required><option value="">Select source</option><?php foreach($branches as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>To branch<select name="to_branch_id" required><option value="">Select destination</option><?php foreach($branches as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Product<select name="product_id" required><option value="">Select product</option><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Quantity<input type="number" step="0.001" min="0.001" name="quantity" required></label><label class="full">Notes<textarea name="notes"></textarea></label></div><div class="form-actions"><a class="btn" href="<?=app_url('transfers.php')?>">Cancel</a><button class="btn primary">Complete transfer</button></div></form></article><?php else:$rows=$pdo->query('SELECT t.*,fb.name from_branch,tb.name to_branch,br.name brand,u.name requested FROM stock_transfers t JOIN branches fb ON fb.id=t.from_branch_id JOIN branches tb ON tb.id=t.to_branch_id JOIN brands br ON br.id=t.brand_id JOIN users u ON u.id=t.requested_by WHERE t.deleted_at IS NULL ORDER BY t.id DESC LIMIT 50')->fetchAll();?><article class="card table-card"><div class="table-toolbar"><div><b><?=count($rows)?> recent transfers</b><small style="display:block;color:var(--muted);margin-top:4px">Branch-to-branch movement history</small></div></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Date</th><th>From</th><th>To</th><th>Brand</th><th>Status</th><th>Requested by</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td data-label="Reference"><b><?=e($r['reference_no'])?></b></td><td data-label="Date"><?=date('d M Y',strtotime($r['transfer_date']))?></td><td data-label="From"><?=e($r['from_branch'])?></td><td data-label="To"><?=e($r['to_branch'])?></td><td data-label="Brand"><?=e($r['brand'])?></td><td data-label="Status"><span class="status"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></span></td><td data-label="Requested by"><?=e($r['requested'])?></td></tr><?php endforeach;?></tbody></table></div></article><?php endif;render_footer('transfers');
